import gzip,json,hashlib,time
from pathlib import Path
import cadquery as cq
import numpy as np
ROOT=Path(__file__).resolve().parents[1];path=ROOT/'exports/slim-thigh-live-fidelity.json.gz';data=gzip.decompress(path.read_bytes());capture=json.loads(data);target=json.loads((ROOT/'manifests/bench-limb-approved-target.json').read_text());rows=[];tick=time.monotonic()
